CREATE COLUMN TABLE "TEST_AP"."OCRC" ("CreditCard" SMALLINT CS_INT NOT NULL , "CardName" NVARCHAR(30) NOT NULL , "AcctCode" NVARCHAR(15), "Phone" NVARCHAR(20), "CompanyId" NVARCHAR(20), "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UpdateDate" LONGDATE CS_LONGDATE, "IntTaxCode" NVARCHAR(2), "UserSign2" SMALLINT CS_INT, "Country" NVARCHAR(3), PRIMARY KEY ("CreditCard")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCRC_CARD_NAME" ON "TEST_AP"."OCRC" ( "CardName" ASC )